    const pathPrefix = this.getSettings().passageFolder.trim().replace(/\/?$/, "/");
    const passages = this.app.vault.getFiles().filter(
      (file) => file.path.startsWith(pathPrefix) && file.extension === "md"
    ).sort((a, b) => b.stat.mtime - a.stat.mtime);
