var resolveLoomApiKey = (preset) => {
  const raw = preset && preset.apiKey ? String(preset.apiKey).trim() : "";
  if (raw && !raw.startsWith("$")) return raw;
  if (raw.startsWith("$")) {
    const envVal = process.env[raw.slice(1)];
    if (envVal && envVal.trim()) return envVal.trim();
  }
  try {
    const fs = require("fs");
    const path = require("path");
    const os = require("os");
    const provider = (preset && preset.provider) || "openrouter";
    const file = path.join(os.homedir(), `.loom-${provider}.key`);
    if (fs.existsSync(file)) {
      const fileVal = fs.readFileSync(file, "utf8").trim();
      if (fileVal) return fileVal;
    }
  } catch (e) {}
  return raw;
};

